export const modelGroups={text:'生文',image:'生图',video:'生视频',audio:'生音频'};
export function modelGroup(step){return step==='image'||step.endsWith('Image')?'image':step==='video'?'video':['voice','music'].includes(step)?'audio':'text'}
export function resolveModel(s,step){const group=modelGroup(step),override=s.models?.[step],base=override||s.modelDefaults?.[group];const projectName=step==='video'&&s.generation?.model&&!s.generation.model.startsWith('演示')?s.generation.model:null;return {...structuredClone(base||{name:'演示模型',capability:group}),...(projectName?{name:projectName}:{}),group,source:projectName?'project':override?'step':base?'category':'unconfigured'};}
export function validateModel(m,group){if(!m?.name?.trim()||!/^https?:\/\/[^\s]+$/.test(m.url||'')||!(+m.timeout>0)||m.capability!==group)throw Error('请填写模型标识、HTTP(S) 服务地址和正数超时；能力须与类别一致。');}
export function resolvePrompt(s,h,step){const id=s.projectPromptBindings?.[step]||s.promptBindings?.[step]||h.config?.promptBindings?.[step]||'prompt-'+step;const r=h.methodLibrary?.find(x=>x.id===id&&x.interactionKey===step);return {resourceId:id,version:r?.version||1,overrideVersion:s.methodOverrides?.[id]?.version||null,text:s.methodOverrides?.[id]?.text??(id==='prompt-'+step?s.prompts?.[step]:undefined)??r?.text??s.defaults?.[step],source:s.methodOverrides?.[id]?'project':'library'};}
